14	import net.officefloor.hq.app.rate.RateService;
15	import net.officefloor.hq.app.role.Role;
16	import net.officefloor.hq.app.role.RoleService;
17	import net.officefloor.hq.app.setting.SettingService;
18	import net.officefloor.hq.app.sheet.Sheet;
19	import net.officefloor.hq.app.sheet.SheetService;
20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	
23	/**
24	 * Keeps the people's claims on a sheet. A claim with no date is dated the sheet's today. A claim dated in a closed
25	 * period cannot be added, edited or change status. Only a DRAFT claim can be edited; a PENDING claim, waiting for a
26	 * steward to approve or reject it, is otherwise handled like an OPEN one. No claim
27	 * can be dated after the retirement date of its person. A claim with a negative amount is a correction: it must name,
28	 * by number, a SETTLED claim of the same person that it corrects, and its due has no floor and no late charge.
29	 */
30	@Service
31	public class ClaimService {
32	
33	    private final ClaimRepository claims;
34	    private final PersonRepository people;
35	    private final RateService rates;
36	    private final SheetService sheets;
37	    private final Audit audit;
38	    private final RollupService rollup;
39	    private final PeriodService periods;
40	    private final RoleService roles;
41	    private final SettingService settings;
42	
43	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
44	            Audit audit, RollupService rollup, PeriodService periods, RoleService roles, SettingService settings) {
45	        this.periods = periods;
46	        this.roles = roles;
47	        this.settings = settings;
48	        this.claims = claims;
49	        this.people = people;
50	        this.rates = rates;
51	        this.sheets = sheets;
52	        this.audit = audit;
53	        this.rollup = rollup;
54	    }
55	
56	    public List<Claim> list(String sheetId) {
57	        return claims.findBySheetIdOrderByIdDesc(sheetId);
58	    }
59	
60	    @Transactional
61	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
62	            String corrects) {
63	        RollupService.Snapshot before = rollup.snapshot(sheetId);
64	        Person person = people.findByIdAndSheetId(personId, sheetId)
65	                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
66	        LocalDate dated = dateOr(sheetId, date);
67	        periods.requireOpen(sheetId, dated);
68	        person.requireClaimable(dated);
69	        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
70	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
71	        claim.setCorrects(corrects);
72	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
73	        Claim saved = claims.saveAndFlush(claim);
74	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved));
75	        rollup.recordChanges(sheetId, user, before);
76	        return saved;
77	    }
78	
79	    @Transactional
80	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
81	            String corrects) {
82	        RollupService.Snapshot before = rollup.snapshot(sheetId);
83	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
84	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
85	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
86	        if (claim.getStatus() != ClaimStatus.DRAFT) {
87	            throw new ClaimNotEditableException(id, claim.getStatus());
88	        }
89	        LocalDate dated = dateOr(sheetId, date);
90	        // Neither out of nor into a closed period.
91	        periods.requireOpen(sheetId, claim.getDate(), dated);
92	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
93	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
94	                .requireClaimable(dated);
95	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
96	        claim.setAmount(amount);
97	        claim.setCorrects(corrects);
98	        claim.setDate(dated);
99	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
100	        claim.setNote(noteOf(note));
101	        Claim saved = claims.saveAndFlush(claim);
102	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
103	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
104	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
105	        rollup.recordChanges(sheetId, user, before);
106	        return saved;
107	    }
108	
109	    /**
110	     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
111	     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
112	     */
113	    @Transactional
114	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
115	        Claim claim = claims.findForUpdate(id, sheetId)
116	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
117	        if (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING) {
118	            throw new ClaimStatusException(id, claim.getStatus(), status);
119	        }
120	        periods.requireOpen(sheetId, claim.getDate());
121	        // Four eyes: whoever opened a claim cannot also settle it.
122	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
123	            throw new ClaimSettledByOpenerException(id, user);
124	        }
125	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
126	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
127	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
128	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
129	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
130	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
131	            BigDecimal due = withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
132	            if (limit != null && due != null && due.compareTo(limit) > 0) {
133	                status = ClaimStatus.PENDING;
134	            }
135	        }
136	        RollupService.Snapshot before = rollup.snapshot(sheetId);
137	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim) : "";
138	        claim.setStatus(status);
139	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
140	        String number = claim.getNumber();
141	        if (status == ClaimStatus.OPEN) {
142	            number = nextNumber(sheetId, claim.getDate());
143	            claim.setNumber(number);
144	            claim.setOpenedBy(user);
145	        }
146	        Claim saved = claims.saveAndFlush(claim);
147	        String event = switch (status) {
148	            case OPEN -> "CLAIM_OPENED";
149	            case PENDING -> "CLAIM_PENDING";
150	            case SETTLED -> "CLAIM_SETTLED";
151	            case VOID -> "CLAIM_VOIDED";
152	            case DRAFT -> throw new IllegalStateException();
153	        };
154	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
155	        rollup.recordChanges(sheetId, user, before);
156	        return saved;
157	    }
158	
159	    /**
160	     * A steward other than its opener approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
161	     * its live figure.
162	     */
163	    @Transactional
164	    public Claim approve(String sheetId, String user, Long id) {
165	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
166	        if (user.equals(claim.getOpenedBy())) {
167	            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
168	        }
169	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
170	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
171	        RollupService.Snapshot before = rollup.snapshot(sheetId);
172	        String due = settle(sheetId, person, claim);
173	        claim.setStatus(ClaimStatus.SETTLED);
174	        Claim saved = claims.saveAndFlush(claim);
175	        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
176	        rollup.recordChanges(sheetId, user, before);
177	        return saved;
178	    }
179	
180	    /**
181	     * A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last statement
182	     * if that statement included it.
183	     */
184	    @Transactional
185	    public Claim reject(String sheetId, String user, Long id, String reason) {
186	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.OPEN);
187	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
188	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
189	        RollupService.Snapshot before = rollup.snapshot(sheetId);
190	        claim.setStatus(ClaimStatus.OPEN);
191	        Claim saved = claims.saveAndFlush(claim);
192	        audit.recordOnCommit(record("CLAIM_REJECTED", user, person, saved) + numberOf(saved.getNumber())
193	                + " reason=" + reason);
194	        rollup.recordChanges(sheetId, user, before);
195	        return saved;
196	    }
197	
198	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
199	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
200	        Claim claim = claims.findForUpdate(id, sheetId)
201	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
202	        if (claim.getStatus() != ClaimStatus.PENDING) {
203	            throw new ClaimStatusException(id, claim.getStatus(), to);
204	        }
205	        periods.requireOpen(sheetId, claim.getDate());
206	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
207	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
208	        }
209	        return claim;
210	    }
211	
212	    /**
213	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
214	     * the rate on the claim's date) with its late charge frozen in; with no figure it stays live. Gives the due at the
215	     * end of its audit record.
216	     */
217	    private String settle(String sheetId, Person person, Claim claim) {
218	        BigDecimal figure = figureOf(sheetId, person, claim);
219	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
220	                : figure.add(settings.get(sheetId).lateCharge(figure, claim.getDate()));
221	        claim.setSettledDue(settledDue);
222	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
223	    }
224	
225	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
226	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
227	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
228	    }
229	
230	    /**
231	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
232	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
233	     * for any other claim.
234	     */
235	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
236	        if (amount.signum() >= 0) {
237	            if (corrects != null) {
238	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
239	            }
240	            return null;
241	        }
242	        if (corrects == null) {
243	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
244	        }
245	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
246	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
247	                .map(Claim::getDate)
248	                .orElseThrow(() -> new ClaimCorrectionException(
249	                        "Claim " + corrects + " is not a settled claim of the same person"));
250	    }
251	
252	    /**
253	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
254	     * date has the claim round, raised to the sheet's floor unless it is a correction; null (n/a) with no rate.
255	     */
256	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
257	        Sheet sheet = settings.get(sheetId);
258	        BigDecimal due = rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
259	                .map(Rate::getPct)
260	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
261	                .orElse(null);
262	        return claim.isCorrection() ? due : sheet.floored(due);
263	    }
264	
265	    /**
266	     * The due with the late charge of an OPEN or PENDING claim overdue on the sheet's today added on top (none on a
267	     * correction); null (n/a) stays null.
268	     */
269	    private BigDecimal withLateCharge(String sheetId, Claim claim, BigDecimal due) {
270	        return settings.get(sheetId).withLateCharge(due,
271	                claim.getStatus().isOpen() && !claim.isCorrection(), claim.getDate());
272	    }
273	
274	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
275	    private static String record(String event, String user, Person person, Claim claim) {
276	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
277	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
278	                + " date=" + claim.getDate();
279	    }
280	
281	    /** The claim's number at the end of an audit record, or nothing when it has none. */
282	    private static String numberOf(String number) {
283	        return number == null ? "" : " number=" + number;
284	    }
285	
286	    /**
287	     * The number a claim dated on the date gets when opened: while the sheet numbers by period, the next in its
288	     * period's own sequence (X for no period); otherwise the next sheet-wide number.
289	     */
290	    private String nextNumber(String sheetId, LocalDate date) {
291	        if (settings.get(sheetId).numbersByPeriod()) {
292	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
293	        }
294	        return String.valueOf(sheets.nextClaimNumber(sheetId));
295	    }
296	
297	    private LocalDate dateOr(String sheetId, LocalDate date) {
298	        return date != null ? date : sheets.today(sheetId);
299	    }
300	
301	    private static String noteOf(String note) {
302	        return note == null ? "" : note.trim();
303	    }
304	}
