3	import jakarta.validation.Valid;
4	import jakarta.validation.constraints.NotBlank;
5	import jakarta.validation.constraints.NotNull;
6	import jakarta.validation.constraints.Pattern;
7	import jakarta.validation.constraints.Size;
8	import java.math.BigDecimal;
9	import java.math.RoundingMode;
10	import java.time.LocalDate;
11	import java.util.List;
12	import org.springframework.http.HttpStatus;
13	import org.springframework.validation.annotation.Validated;
14	import org.springframework.web.bind.annotation.GetMapping;
15	import org.springframework.web.bind.annotation.PathVariable;
16	import org.springframework.web.bind.annotation.PostMapping;
17	import org.springframework.web.bind.annotation.PutMapping;
18	import org.springframework.web.bind.annotation.RequestBody;
19	import org.springframework.web.bind.annotation.RequestHeader;
20	import org.springframework.web.bind.annotation.RequestMapping;
21	import org.springframework.web.bind.annotation.ResponseStatus;
22	import org.springframework.web.bind.annotation.RestController;
23	
24	/** The people's claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
25	@RestController
26	@RequestMapping("/api/sheets/{sheetId}")
27	@Validated
28	public class ClaimController {
29	
30	    /**
31	     * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
32	     * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
33	     * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
34	     * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
35	     * own, or a correction's corrected claim's).
36	     */
37	    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
38	            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
39	            LocalDate roundingDate) {
40	
41	        static ClaimView of(Claim claim) {
42	            return new ClaimView(claim.getId(), claim.getPersonId(),
43	                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
44	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
45	                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
46	                    claim.getOpenedBy(), claim.isStated(),
47	                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
48	                    claim.getCorrects(), claim.getRoundingDate());
49	        }
50	    }
51	
52	    /**
53	     * An amount with up to two decimals, negative only for a correction; a missing date takes the sheet's today; the
54	     * number of the claim a correction corrects, blank for any other claim.
55	     */
56	    public record ClaimRequest(
57	            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
58	            LocalDate date,
59	            @Size(max = 1000) String note,
60	            @Size(max = 255) String corrects) {
61	
62	        BigDecimal amountValue() {
63	            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
64	        }
65	
66	        String correctsValue() {
67	            if (corrects == null || corrects.isBlank()) {
68	                return null;
69	            }
70	            // A sheet-wide number is written without leading zeros; a period number (P1-1, X-1) as typed.
71	            String trimmed = corrects.trim();
72	            return trimmed.matches("\\d{1,18}") ? String.valueOf(Long.parseLong(trimmed)) : trimmed;
73	        }
74	    }
75	
76	    /** The ids of the claims selected to open together. */
77	    public record BulkOpenRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
78	    }
79	
80	    private final ClaimService service;
81	    private final BulkOpenService bulkOpen;
82	
83	    public ClaimController(ClaimService service, BulkOpenService bulkOpen) {
84	        this.service = service;
85	        this.bulkOpen = bulkOpen;
86	    }
87	
88	    /** All the sheet's claims, newest first. */
89	    @GetMapping("/claims")
90	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
91	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
92	        return service.list(sheetId.trim()).stream().map(ClaimView::of).toList();
93	    }
94	
95	    @PostMapping("/people/{personId}/claims")
96	    @ResponseStatus(HttpStatus.CREATED)
97	    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
98	            @PathVariable Long personId,
99	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
100	            @RequestBody @Valid ClaimRequest request) {
101	        return ClaimView.of(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.date(),
102	                request.note(), request.correctsValue()));
103	    }
104	
105	    /** Edit a DRAFT claim; refused for any other status. */
106	    @PutMapping("/claims/{id}")
107	    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
108	            @PathVariable Long id,
109	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
110	            @RequestBody @Valid ClaimRequest request) {
111	        return ClaimView.of(service.update(sheetId.trim(), user.trim(), id, request.amountValue(), request.date(),
112	                request.note(), request.correctsValue()));
113	    }
114	
115	    /** Open a DRAFT claim. */
116	    @PostMapping("/claims/{id}/open")
117	    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
118	            @PathVariable Long id,
119	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
120	        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.OPEN));
121	    }
122	
123	    /** Open the selected claims in list order; each one that cannot be opened is left as it is. */
124	    @PostMapping("/claims/bulk-open")
125	    public BulkOpenService.Result bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
126	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
127	            @RequestBody @Valid BulkOpenRequest request) {
128	        return bulkOpen.open(sheetId.trim(), user.trim(), request.ids());
129	    }
130	
131	    /** Settle an OPEN claim; refused to the user who opened it; PENDING instead when a clerk settles it above the clerk limit. */
132	    @PostMapping("/claims/{id}/settle")
133	    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
134	            @PathVariable Long id,
135	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
136	        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.SETTLED));
137	    }
138	
139	    /** A steward's reason for rejecting a PENDING claim. */
140	    public record RejectRequest(@NotBlank @Size(max = 1000) String reason) {
141	    }
142	
143	    /** Approve a PENDING claim: a steward only, and not the one who opened it. */
144	    @PostMapping("/claims/{id}/approve")
145	    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
146	            @PathVariable Long id,
147	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
148	        return ClaimView.of(service.approve(sheetId.trim(), user.trim(), id));
149	    }
150	
151	    /** Reject a PENDING claim with a reason, back to OPEN: a steward only. */
152	    @PostMapping("/claims/{id}/reject")
153	    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
154	            @PathVariable Long id,
155	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
156	            @RequestBody @Valid RejectRequest request) {
157	        // One line in the audit file: any run of white space in the reason becomes a single space.
158	        String reason = request.reason().trim().replaceAll("\\s+", " ");
159	        return ClaimView.of(service.reject(sheetId.trim(), user.trim(), id, reason));
160	    }
161	
162	    /** Void a DRAFT, OPEN or PENDING claim. */
163	    @PostMapping("/claims/{id}/void")
164	    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
165	            @PathVariable Long id,
166	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
167	        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.VOID));
168	    }
169	}
